package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Properties;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLine_GetOptionPropertiesTest {

    // Helper to construct a CommandLine instance via the private constructor
    private CommandLine createCommandLine(List<String> args, List<Option> options, Consumer<Option> deprecatedHandler) throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);
        return ctor.newInstance(args, options, deprecatedHandler);
    }

    // Helper to invoke getOptionProperties via reflection
    private Properties invokeGetOptionProperties(CommandLine cmd, String name) throws Exception {
        Method m = CommandLine.class.getMethod("getOptionProperties", String.class);
        Object result = m.invoke(cmd, name);
        return (Properties) result;
    }

    @Test
    public void testGetOptionPropertiesByOpt() throws Exception {
        // prepare option with opt "x"
        Option optX = new Option("x", "ex", true, "desc");
        // populate values list with key=value pairs
        optX.getValuesList().add("k1=v1");
        optX.getValuesList().add("k2=v2");

        List<Option> options = new ArrayList<>();
        options.add(optX);

        CommandLine cmd = createCommandLine(new LinkedList<>(), options, null);

        Properties props = invokeGetOptionProperties(cmd, "x");

        assertNotNull(props);
        assertEquals(2, props.size());
        assertEquals("v1", props.getProperty("k1"));
        assertEquals("v2", props.getProperty("k2"));
    }

    @Test
    public void testGetOptionPropertiesByLongOpt() throws Exception {
        // prepare option with longOpt "long-name"
        Option opt = new Option("l", "long-name", true, "desc");
        opt.getValuesList().add("alpha=one");
        opt.getValuesList().add("beta=two");

        List<Option> options = new ArrayList<>();
        options.add(opt);

        CommandLine cmd = createCommandLine(new LinkedList<>(), options, null);

        Properties props = invokeGetOptionProperties(cmd, "long-name");

        assertNotNull(props);
        assertEquals(2, props.size());
        assertEquals("one", props.getProperty("alpha"));
        assertEquals("two", props.getProperty("beta"));
    }

    @Test
    public void testGetOptionPropertiesMultipleOptionsAndOverride() throws Exception {
        // two options with same opt "o" that both match; second should override overlapping keys
        Option first = new Option("o", "opt-one", true, "first");
        first.getValuesList().add("k1=v1");
        first.getValuesList().add("k2=v2");

        Option second = new Option("o", "opt-two", true, "second");
        second.getValuesList().add("k2=override");
        second.getValuesList().add("k3=v3");

        List<Option> options = new ArrayList<>();
        options.add(first);
        options.add(second);

        CommandLine cmd = createCommandLine(new LinkedList<>(), options, null);

        Properties props = invokeGetOptionProperties(cmd, "o");

        assertNotNull(props);
        assertEquals(3, props.size());
        assertEquals("v1", props.getProperty("k1"));
        // ensure second option's value overrides the first for k2
        assertEquals("override", props.getProperty("k2"));
        assertEquals("v3", props.getProperty("k3"));
    }

    @Test
    public void testGetOptionPropertiesNoMatchReturnsEmpty() throws Exception {
        Option opt = new Option("a", "alpha", true, "desc");
        opt.getValuesList().add("some=val");

        List<Option> options = new ArrayList<>();
        options.add(opt);

        CommandLine cmd = createCommandLine(new LinkedList<>(), options, null);

        Properties props = invokeGetOptionProperties(cmd, "nonexistent");

        assertNotNull(props);
        assertTrue(props.isEmpty());
    }
}

